'use strict';
// Original contract: projects own a tender document and multiple bidders;
// each enabled mode runs all rules attached to its chosen prompt.
const baBase={workbench,configPanel,seedConfig,handleAction,modalContent,pickerModal,twMountPreview,validate,configurationFragment,pgLibrary};
const BA_MODES=[['tender','招标文件分析','bidding_only','核查资格条件、评分办法和招标条款。'],['bid','投标文件分析','tender_only','比对投标单位的围标串标关联线索。'],['joint','招投标联合分析','joint_only','对照招标要求，核查投标响应与报价。']];
// Names, IDs and focus text come from the original biddingAnalysisTemplateMock.
// The live service may supply a longer list; never truncate or replace that list.
const BA_RULES={
 tender:[['b1','资格合规性','核对投标人资质、业绩、人员等条件是否与法规及项目要求一致。'],['b2','评分标准完整性','检查评分办法是否完整、量化指标是否清晰、分值分配是否合理。'],['b3','招标条款一致性','识别招标文件前后条款、附件与正文之间是否存在矛盾或不一致。'],['b4','实质性要求识别','提取并标注实质性条款，识别表述模糊或缺少客观判定标准的否决项。'],['b5','条款歧视性识别','识别指定品牌、不合理资质门槛、地域限制等可能构成歧视的条款。'],['b6','不合理的资质与加分项','评估资质条件与项目匹配度，识别过高门槛或不合理加分设置。'],['b7','评审办法中的“主观分”陷阱','识别主观评分占比过高、缺少可操作判定标准的情形。']],
 bid:[['t5','围标串标风险识别','比对元数据、联系方式、人员交叉、文本相似度等串标关联特征。']],
 joint:[['j1','投标文件应废未废','对照招标废标条款与实质性要求，判断是否存在应废未废风险。'],['t1','投标文件格式合规','检查投标文件目录、签章、有效期、保证金等格式性要求是否满足。'],['t2','报价合理性识别','分析报价构成、单价合理性及是否存在异常低价或报价规律。'],['t3','技术响应偏离检测','对照招标技术要求，识别负偏离、未响应及关键参数不满足项。'],['t4','资质证书有效性识别','核验资质证书类型、等级、有效期及人员证书匹配情况。'],['t6','投标文件错同样的地方','识别不同投标文件中相同错误、相同异常表述等可疑一致性。'],['t7','低于成本价竞标的分析','结合报价与成本要素，识别疑似低于成本价竞标的情形。']]
};
const baView={project:null,stage:null,panel:'materials',query:'',page:1,size:20,unitQuery:'',unitPage:1,pendingPage:1,fileLimits:{}};
const baOldDefaults=structuredClone(PG_ROOT_DEFAULTS.bidding);
for(const [key,label,,focus] of BA_MODES){
 const rules=BA_RULES[key].map(([id,name,description])=>({id,name,description}));
 const source={templateId:{tender:'bidding-std',bid:'tender-std',joint:'joint-std'}[key],ruleIds:rules.map(r=>r.id),rules};
 PG_ROOT_DEFAULTS.bidding.bidding??={};PG_ROOT_DEFAULTS.bidding.bidding[key]=source;
 const s=PG_ROOT_DEFAULTS.bidding.stages[key];
 s.content='你是一名招投标合规审计助手。'+focus+'\n\n检查规则：\n'+rules.map(r=>r.id+' '+r.name+'：'+r.description).join('\n')+'\n\n按规则编号输出风险等级（高/中/低/无）、置信度、分析说明和关键证据位置；当前资料中无明显问题时写明“未发现风险”，资料不足时如实说明，保留需进一步核验的事项。';
 s.promptConfig={bidding:{[key]:structuredClone(source)}};
}
function baActive(){return state.view==='tool'&&state.toolId==='bidding';}
function baPreparing(){return baActive()&&!currentTask();}
seedConfig=function(id,c){baBase.seedConfig(id,c);if(id!=='bidding'||c!==state.work.bidding?.config||state.work.bidding.taskId)return c;for(const [key] of BA_MODES){const s=c.stages[key],old=baOldDefaults.stages[key],d=PG_ROOT_DEFAULTS.bidding.stages[key];if(s&&!s.customized&&s.origin==='system'&&(!s.pgChoice||s.pgChoice==='system')&&s.template===old.template&&[old.content,d.content].includes(s.content)&&!s.promptConfig&&!c.bidding?.[key]){s.content=d.content;s.pgChoice='system';s.scope='public';s.category='system';s.promptConfig=structuredClone(d.promptConfig);}}return c;};
function baConfig(){return currentTask()?.config||ws().config;}
function baSource(c,key){return c.stages?.[key]?.promptConfig?.bidding?.[key]||c.bidding?.[key]||{};}
function baRules(c,key){const src=baSource(c,key),meta=Array.isArray(src.rules)?src.rules:[],ids=Array.isArray(src.ruleIds)?src.ruleIds:meta.map(r=>typeof r==='string'?r:r.id||r.ruleId);return [...new Set(ids)].map(id=>{const raw=meta.find(r=>(typeof r==='string'?r:r.id||r.ruleId)===id),fallback=BA_RULES[key].find(r=>r[0]===id);return{id,name:typeof raw==='string'?raw:raw?.name||raw?.label||fallback?.[1]||String(id),description:typeof raw==='object'?(raw.description||raw.focus||raw.defaultPrompt||fallback?.[2]||''):fallback?.[2]||''};});}
function baRecordConfig(t){try{const raw=t.promptConfig||t.config||{},c=typeof raw==='string'?JSON.parse(raw):raw;return c.config||c;}catch{return {};}}
pgLibrary=function(id,key){const items=baBase.pgLibrary(id,key);if(id!=='bidding')return items;return items.filter(item=>{if(item.value==='system')return true;const t=state.templates.find(t=>'p:'+t.id===item.value),mode=baRecordConfig(t||{}).analysis_mode;return !mode||mode===BA_MODES.find(m=>m[0]===key)?.[2]||key==='joint'&&mode==='both';});};
function baModes(){const modes=currentTask()?.modes||ws().modes;return BA_MODES.filter(m=>modes.includes(m[0]));}
function baStage(){const modes=baModes();if(!modes.some(m=>m[0]===baView.stage))baView.stage=modes[0]?.[0]||null;return baView.stage;}
function baProject(){const ps=ws().projects;if(!ps.some(p=>p.id===baView.project))baView.project=ps[0]?.id||null;return ps.find(p=>p.id===baView.project);}
function baProjectIssue(p,modes=ws().modes){if(!p)return '请添加项目';const hasFiles=p.tender.length||p.bidders.some(b=>b.files.length);if(!hasFiles)return '待添加文件';if(!p.name.trim())return '待填写项目名称';if((modes.includes('tender')||modes.includes('joint'))&&!p.tender.length)return '缺少招标文件';if((modes.includes('bid')||modes.includes('joint'))&&!p.bidders.some(b=>b.files.length))return '缺少投标文件';if(p.bidders.some(b=>b.files.length&&!b.name.trim()))return '待填写投标单位名称';return '';}
function baStats(w=ws()){return{projects:w.projects.length,tender:w.projects.reduce((n,p)=>n+p.tender.length,0),units:w.projects.reduce((n,p)=>n+p.bidders.filter(b=>b.files.length).length,0),bid:w.projects.reduce((n,p)=>n+p.bidders.reduce((n,b)=>n+b.files.length,0),0)};}
function baIcon(action,icon,label,attrs=''){return B(I(icon,'icon-sm'),action,'ghost sm ba-icon','aria-label="'+E(label)+'" title="'+E(label)+'" '+attrs);}
function baFiles(ids,p,role,index){const token=p.id+':'+role+':'+index,limit=baView.fileLimits[token]||5;return ids.slice(0,limit).map(id=>'<div class="ba-file">'+I('file','icon-sm')+A(E(file(id)?.name||'原文件已移除'),'source','data-id="'+E(id)+'" title="'+E(file(id)?.name||'原文件已移除')+'"')+baIcon('remove-bidfile','close','移除文件关联','data-id="'+E(id)+'" data-project="'+E(p.id)+'" data-role="'+role+'" data-index="'+(index??'')+'"')+'</div>').join('')+(ids.length>limit?B('再显示 '+Math.min(20,ids.length-limit)+' 份（共 '+ids.length+' 份）','ba-files-more','ghost sm','data-key="'+E(token)+'"'):'');}
function baPending(){const ids=ws().unassigned||[];if(!ids.length)return '';const pages=Math.ceil(ids.length/10);baView.pendingPage=Math.min(baView.pendingPage,pages);return '<details class="ba-pending" open><summary>待分配资料 <strong>'+ids.length+'</strong></summary><p>指定项目及招标或投标角色后，才能参与分析。</p>'+ids.slice((baView.pendingPage-1)*10,baView.pendingPage*10).map(id=>'<div class="ba-pending-file"><span title="'+E(file(id)?.name)+'">'+E(file(id)?.name)+'</span>'+A('分配','assign-bid','data-id="'+E(id)+'"')+baIcon('remove-file','close','取消本次选择','data-id="'+E(id)+'"')+'</div>').join('')+(pages>1?'<div class="ba-small-pages">'+B('上页','ba-pending-page','ghost sm','data-step="-1" '+(baView.pendingPage===1?'disabled':''))+'<span>'+baView.pendingPage+' / '+pages+'</span>'+B('下页','ba-pending-page','ghost sm','data-step="1" '+(baView.pendingPage===pages?'disabled':''))+'</div>':'')+'</details>';}
function baMaterials(){const w=ws(),p=baProject(),s=baStats(),q=baView.unitQuery.trim().toLowerCase(),units=(p?.bidders||[]).map((b,index)=>({b,index})).filter(({b})=>(b.name+' '+b.files.map(id=>file(id)?.name).join(' ')).toLowerCase().includes(q)),pages=Math.max(1,Math.ceil(units.length/10));baView.unitPage=Math.min(baView.unitPage,pages);const issue=baProjectIssue(p);return '<aside class="ba-materials ew-materials"><div class="ba-panel-head"><h2><span class="tw-step">Step 1</span> 配置项目资料</h2>'+B('新增项目','add-project','sm')+'</div><div class="ba-project-switch"><label>当前项目<select data-ba-change="project" aria-label="切换分析项目">'+w.projects.map((x,i)=>'<option value="'+E(x.id)+'" '+(x.id===p?.id?'selected':'')+'>'+E((i+1)+'. '+(x.name||'未命名项目'))+'</option>').join('')+'</select></label></div><div class="ba-material-scroll">'+baPending()+(p?'<section class="ba-project"><div class="ba-name-row"><label>项目名称<input data-project="'+E(p.id)+'" aria-label="项目名称" value="'+E(p.name)+'" maxlength="100"></label>'+(w.projects.length>1?baIcon('remove-project','close','移除当前项目及文件关联','data-id="'+E(p.id)+'"'):'')+'</div><section class="ba-tender-slot"><div class="ba-section-heading"><h3>招标文件 <strong>'+p.tender.length+'</strong></h3>'+B(p.tender.length?'更换':'选择文件','pick-bid','sm soft','data-project="'+E(p.id)+'" data-role="tender"')+'</div>'+baFiles(p.tender,p,'tender')+(!p.tender.length?'<p class="ba-muted">招标及联合分析需提供招标文件。</p>':'')+'</section><section class="ba-bidders"><div class="ba-section-heading"><h3>投标单位 <strong>'+p.bidders.length+'</strong></h3>'+A('新增单位','add-bidder','data-id="'+E(p.id)+'"')+'</div>'+(p.bidders.length>5?'<div class="search ba-unit-search">'+I('search','icon-sm')+'<input id="ba-unit-query" data-ba-input="units" aria-label="查找投标单位或文件" placeholder="查找单位或文件" value="'+E(baView.unitQuery)+'"></div>':'')+units.slice((baView.unitPage-1)*10,baView.unitPage*10).map(({b,index})=>'<section class="ba-bidder"><div class="ba-name-row"><label>单位名称<input data-bidder="'+E(p.id)+':'+index+'" aria-label="投标单位名称" placeholder="请输入单位名称" maxlength="100" value="'+E(b.name)+'"></label>'+baIcon('remove-bidder','close','移除投标单位及文件关联','data-project="'+E(p.id)+'" data-index="'+index+'"')+'</div><div class="ba-section-heading"><span>投标文件 <strong>'+b.files.length+'</strong></span>'+B(b.files.length?'添加 / 更换':'选择文件','pick-bid','ghost sm','data-project="'+E(p.id)+'" data-role="bid" data-index="'+index+'"')+'</div>'+baFiles(b.files,p,'bid',index)+'</section>').join('')+(!units.length?'<p class="ba-muted">'+(q?'没有匹配的单位或文件。':'点击“新增单位”，再选择该单位的投标文件。')+'</p>':'')+(pages>1?'<div class="ba-small-pages">'+B('上一页','ba-unit-page','sm','data-step="-1" '+(baView.unitPage===1?'disabled':''))+'<span>第 '+baView.unitPage+' / '+pages+' 页</span>'+B('下一页','ba-unit-page','sm','data-step="1" '+(baView.unitPage===pages?'disabled':''))+'</div>':'')+'</section></section>':'<p class="ba-muted">新增项目后，分别添加招标文件和各单位投标文件。</p>')+'</div><div class="ba-material-footer"><p id="ba-project-status" class="'+(issue?'ba-waiting':'ba-ready')+'">'+E(issue||'当前项目资料已配置')+'</p><span>本次 <strong>'+s.projects+'</strong> 个项目 · 招标 <strong>'+s.tender+'</strong> 份 · 投标 <strong>'+s.bid+'</strong> 份</span></div></aside>';}
function baFilteredRules(c=baConfig(),key=baStage()){const query=baView.query.trim().toLowerCase();return key?baRules(c,key).filter(r=>(r.name+' '+r.description+' '+r.id).toLowerCase().includes(query)):[];}
function baRuleRows(c=baConfig(),key=baStage()){const all=baFilteredRules(c,key),pages=Math.max(1,Math.ceil(all.length/baView.size));baView.page=Math.max(1,Math.min(baView.page,pages));const start=(baView.page-1)*baView.size;return '<div class="ba-rule-table-wrap"><table class="ba-rule-table"><thead><tr><th>序号</th><th>检查规则</th><th>检查重点</th><th>操作</th></tr></thead><tbody>'+all.slice(start,start+baView.size).map((r,i)=>'<tr><td>'+(start+i+1)+'</td><td><button class="link" data-action="ba-rule-detail" data-stage="'+key+'" data-id="'+E(String(r.id))+'">'+E(r.name)+'</button></td><td><div class="ba-rule-focus">'+E(r.description||'检查说明见提示词正文。')+'</div></td><td>'+A('查看','ba-rule-detail','data-stage="'+key+'" data-id="'+E(String(r.id))+'" aria-label="查看'+E(r.name)+'"')+'</td></tr>').join('')+'</tbody></table>'+(!all.length?'<div class="ba-empty-rules">'+(baView.query?'没有匹配规则，请调整关键词。':'该提示词未附带规则清单，分析按提示词正文执行。')+'</div>':'')+'</div><div class="ba-rule-pager"><span>共 <strong>'+all.length+'</strong> 项'+(baView.query?'匹配规则':'规则')+'</span><label>每页 <select data-ba-change="size" aria-label="每页规则数">'+[20,50,100].map(n=>'<option value="'+n+'" '+(baView.size===n?'selected':'')+'>'+n+'</option>').join('')+'</select> 项</label><div>'+B('上一页','ba-rule-page','sm','data-step="-1" '+(baView.page===1?'disabled':''))+'<span>第 '+baView.page+' / '+pages+' 页</span>'+B('下一页','ba-rule-page','sm','data-step="1" '+(baView.page===pages?'disabled':''))+'</div></div>';}
function baModeOptions(c,key,locked,modes){return '<div class="ba-mode-options" aria-label="勾选要执行的分析，可多选">'+BA_MODES.map(([id,label,,help])=>{const selected=modes.some(m=>m[0]===id);return '<div class="ba-mode-option '+(selected?'selected':'')+(key===id?' viewing':'')+'"><label title="'+E(help)+'"><input type="checkbox" data-ba-change="mode" value="'+id+'" '+(selected?'checked':'')+' '+(locked?'disabled':'')+'><b><span class="ba-mode-full">'+label+'</span><span class="ba-mode-short">'+({tender:'招标分析',bid:'投标分析',joint:'联合分析'}[id])+'</span></b></label>'+B((key===id?'当前规则':'查看规则')+' <strong>'+baRules(c,id).length+'</strong>','ba-stage','ghost sm','data-stage="'+id+'" aria-pressed="'+(key===id)+'" '+(selected?'':'disabled'))+'</div>';}).join('')+'</div>';}
function baPanel(){const c=baConfig(),key=baStage(),s=key?c.stages[key]:null,locked=!!currentTask(),modes=baModes();return '<aside class="config ew-config tw-config pg-config ba-config"><div class="ba-panel-head"><h2><span class="tw-step">'+(locked?'执行配置':'Step 2')+'</span> 设置分析内容</h2>'+'</div>'+baModeOptions(c,key,locked,modes)+(s?'<section class="pg-stage-card ba-prompt" data-pg-stage-card="'+key+'"><div class="ba-prompt-select"><div class="pg-select-label"><span class="ba-prompt-label">'+(locked?'本次提示词':'分析提示词')+'</span>'+pgSelect('bidding',key,s,'data-pg-prompt="'+key+'" '+(locked?'disabled':''))+'</div>'+B(locked?'查看提示词':'编辑提示词','aw-prompt','sm','data-stage="'+key+'"')+'</div></section><section class="ba-rules"><div class="ba-rules-head"><div><h3>检查规则 <strong>'+baRules(c,key).length+'</strong></h3><p>本次执行此提示词的全部规则。</p></div><div class="search">'+I('search','icon-sm')+'<input id="ba-rule-query" data-ba-input="rules" aria-label="查找检查规则" placeholder="查找规则名称或检查重点" value="'+E(baView.query)+'">'+(baView.query?baIcon('ba-clear-query','close','清除规则查找'):'')+'</div></div><div class="ba-rule-results" id="ba-rule-results">'+baRuleRows(c,key)+'</div></section>':'<div class="ba-empty-rules">请至少选择一种分析内容。</div>')+'</aside>';}
configPanel=function(){return baActive()?baPanel():baBase.configPanel();};
workbench=function(){if(!baPreparing())return baBase.workbench();seedConfig('bidding',ws().config);return '<div class="ew-workspace ba-workspace">'+twHeader()+'<nav class="ba-mobile-tabs" aria-label="招投标分析工作区">'+B('项目资料','ba-panel',baView.panel==='materials'?'active':'','data-panel="materials"')+B('分析内容与规则','ba-panel',baView.panel==='config'?'active':'','data-panel="config"')+'</nav><div class="ba-layout" data-ba-panel="'+baView.panel+'">'+baMaterials()+baPanel()+'</div></div>';};
twMountPreview=function(){if(baPreparing())return;return baBase.twMountPreview();};
function baPaintRules(){const box=$('#ba-rule-results');if(box){box.innerHTML=baRuleRows();const table=box.querySelector('.ba-rule-table-wrap');if(table)table.scrollTop=0;}}
function baPickerSingle(){return baPreparing()&&modal==='picker'&&modalData.bid&&modalData.role==='tender';}
pickerModal=function(){const html=baBase.pickerModal();if(!baPickerSingle())return html;const root=document.createElement('div');root.innerHTML=html;root.querySelectorAll('[data-action="picker-all"],[data-action="picker-range-keep-page"],[data-change="picker-page"]').forEach(n=>n.remove());root.querySelectorAll('[data-change="picker-check"]').forEach(n=>{n.type='radio';n.name='ba-tender-file';});const note=root.querySelector('.picker-ready-note');if(note)note.textContent='每个项目选择1份已解析的招标文件；选择新文件后替换原关联。';return root.innerHTML;};
validate=function(show=true){if(!baPreparing())return baBase.validate(show);const w=ws(),errors=baBase.validate(false).filter(e=>e==='请填写项目名称'?w.projects.some(p=>(p.tender.length||p.bidders.some(b=>b.files.length))&&!p.name.trim()):!w.projects.filter(p=>!p.tender.length&&!p.bidders.some(b=>b.files.length)).some(p=>e.startsWith(p.name+'：')));if(!w.projects.some(p=>p.tender.length||p.bidders.some(b=>b.files.length)))errors.push('请至少配置一个项目的招标或投标文件');for(const p of w.projects){for(const id of [...p.tender,...p.bidders.flatMap(b=>b.files)]){const d=file(id);if(!d||!pickerRangeEligible(d))errors.push((p.name||'项目')+'：'+(d?.name||'资料')+'未解析完成或没有分析权限');}if(p.tender.length>1)errors.push(p.name+'：每个项目保留1份招标文件，请更换文件');}const unique=[...new Set(errors)];if(show&&unique.length)openModal('validation',{errors:unique});return unique;};
configurationFragment=function(id,c){if(id!=='bidding')return baBase.configurationFragment(id,c);const task=currentTask(),w=task?.toolId==='bidding'&&task.config===c?task:ws('bidding'),modes=BA_MODES.filter(m=>w.modes.includes(m[0])),doc=id=>({file_uuid:id,file_name:file(id)?.name||''});return{analysis_modes:modes.map(m=>m[2]),mode_configs:modes.map(([key,,mode])=>({mode,template_id:baSource(c,key).templateId||'',prompt_id:c.stages[key].backendId!=null?String(c.stages[key].backendId):null,prompt_text:c.stages[key].content,prompt_customized:!!c.stages[key].customized,rule_ids:baRules(c,key).map(r=>r.id)})),projects:w.projects.filter(p=>p.tender.length||p.bidders.some(b=>b.files.length)).map((p,i)=>({sort_order:i+1,project_name:p.name,bidding_file:p.tender[0]?doc(p.tender[0]):null,tender_companies:p.bidders.filter(b=>b.files.length).map((b,i)=>({sort_order:i+1,company_name:b.name,files:b.files.map(doc)}))}))};};
modalContent=function(){if(baActive()&&modal==='ba-rule-detail'){const p=modalData,r=baRules(baConfig(),p.stage).find(r=>String(r.id)===p.id);if(!r)return modalFrame('检查规则','','该规则已更新，请关闭后重新查看。',B('关闭','close-modal'),'medium');return modalFrame(r.name,BA_MODES.find(m=>m[0]===p.stage)[1],'<dl class="ba-rule-detail"><dt>检查重点</dt><dd>'+E(r.description||'检查说明见所选提示词正文。')+'</dd><dt>所属提示词</dt><dd>'+E(baConfig().stages[p.stage].template)+'</dd><dt>规则编号</dt><dd>'+E(String(r.id))+'</dd></dl>',B('关闭','close-modal')+(!currentTask()?B('编辑分析提示词','ba-detail-prompt','primary','data-stage="'+p.stage+'"'):''),'medium');}return baBase.modalContent();};
handleAction=function(action,el){if(!baActive())return baBase.handleAction(action,el);const v=baView,ds=el?.dataset||{};
 if(action==='ba-stage'){if(!baModes().some(m=>m[0]===ds.stage))return;v.stage=ds.stage;v.query='';v.page=1;render();return;}
 if(action==='ba-panel'){v.panel=ds.panel;render();return;}
 if(action==='ba-rule-page'){v.page+=Number(ds.step);baPaintRules();return;}
 if(action==='ba-clear-query'){v.query='';v.page=1;const input=$('#ba-rule-query');if(input){input.value='';input.focus();}baPaintRules();return;}
 if(action==='ba-rule-detail'){openModal('ba-rule-detail',{stage:ds.stage,id:String(ds.id)});return;}
 if(action==='ba-detail-prompt')return pgOpen(ds.stage);
 if(!baPreparing())return baBase.handleAction(action,el);
 if(['remove-file','tw-remove'].includes(action)){const w=ws(),id=ds.id;if(!w.ids.includes(id))return;const before={ids:[...w.ids],projects:structuredClone(w.projects),unassigned:[...(w.unassigned||[])],preview:w.preview};removeWorkFile(id);toast('已移出本次分析，原文件保留。',()=>{Object.assign(w,structuredClone(before));persist();if(state.work.bidding===w)render();});return;}
 if(action==='ba-unit-page'){v.unitPage+=Number(ds.step);render();return;}
 if(action==='ba-pending-page'){v.pendingPage+=Number(ds.step);render();return;}
 if(action==='ba-files-more'){v.fileLimits[ds.key]=(v.fileLimits[ds.key]||5)+20;render();return;}
 if(action==='preview'){if(ws().ids.includes(ds.id))return baBase.handleAction('source',el);return;}
 if(action==='tw-panel'){v.panel=ds.panel==='materials'?'materials':'config';render();return;}
 if(action==='add-project'){baBase.handleAction(action,el);v.project=ws().projects.at(-1)?.id;v.unitQuery='';v.unitPage=1;render();return;}
 if(action==='add-bidder'){baBase.handleAction(action,el);v.unitQuery='';v.unitPage=Math.ceil(baProject().bidders.length/10);render();return;}
 if(baPickerSingle()&&action==='confirm-picker'&&modalData.selected.length>1){toast('每个项目请选择1份招标文件。');return;}
 if(action==='confirm-assign-bid'&&modal==='assign-bid'){const [pid,role]=$('#assign-role').value.split(':'),p=ws().projects.find(p=>p.id===pid);if(role==='tender'&&p.tender.length&&!p.tender.includes(modalData.id)){toast('该项目已有招标文件，请先移除原关联或选择其他角色。');return;}}
 return baBase.handleAction(action,el);
};
window.addEventListener('change',e=>{if(!baActive())return;const el=e.target,key=el.dataset.baChange;if(key){e.stopImmediatePropagation();if(key==='size'){baView.size=Number(el.value);baView.page=1;return baPaintRules();}if(currentTask())return;if(key==='project'){baView.project=el.value;baView.unitQuery='';baView.unitPage=1;}if(key==='mode'){const modes=ws().modes;if(!el.checked&&modes.length===1){el.checked=true;toast('请至少保留一种分析内容。');return;}ws().modes=BA_MODES.map(m=>m[0]).filter(k=>k===el.value?el.checked:modes.includes(k));if(el.checked)baView.stage=el.value;baView.query='';baView.page=1;}render();return;}if(baPickerSingle()&&el.dataset.change==='picker-check'){e.stopImmediatePropagation();if(pickerRangeEligible(file(el.dataset.id)))modalData.selected=[el.dataset.id];paintModal();}},true);
window.addEventListener('input',e=>{if(!baActive())return;const el=e.target,key=el.dataset.baInput;if(key){e.stopImmediatePropagation();if(key==='rules'){baView.query=el.value;baView.page=1;baPaintRules();}if(key==='units'&&!currentTask()){const caret=el.selectionStart;baView.unitQuery=el.value;baView.unitPage=1;render();const input=$('#ba-unit-query');input?.focus();input?.setSelectionRange(caret,caret);}return;}},true);
// Name edits update only the status text; keep the editing input mounted for IME.
window.addEventListener('input',e=>{if(!baPreparing()||!e.target.matches('input[data-project],input[data-bidder]'))return;const p=baProject(),status=$('#ba-project-status'),issue=baProjectIssue(p);if(status){status.textContent=issue||'当前项目资料已配置';status.className=issue?'ba-waiting':'ba-ready';}if(e.target.dataset.project){const option=$('[data-ba-change="project"] option:checked');if(option)option.textContent=(ws().projects.indexOf(p)+1)+'. '+p.name;}});
render();
